contract InvMutTest {
    C c;

    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 x) public payable {
        require(true);

        address owner = c.owner(); if (__ESBMC_reverted()) return;
        uint256 beforeBal = c.balanceOf(owner); if (__ESBMC_reverted()) return;
        uint256 beforeSupply = c.totalSupply(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.burn(x); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterBal = c.balanceOf(owner); if (__ESBMC_reverted()) return;
        uint256 afterSupply = c.totalSupply(); if (__ESBMC_reverted()) return;

        bool successExpected = x <= beforeBal;
        bool successObserved = !reverted;
        bool stateCorrect = reverted
            ? (afterBal == beforeBal && afterSupply == beforeSupply)
            : (afterBal + x == beforeBal && afterSupply + x == beforeSupply);

        assert(successObserved == successExpected && stateCorrect);
    }

    receive() external payable {}
}

